create or replace function public.moderate_inpolor_review(p_review_id uuid,p_action text,p_note text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_previous text; v_next text; v_user_id uuid; begin if not private.can_moderate_inpolor_content() then raise exception using errcode='42501',message='Content moderator access is required.'; end if; select status,user_id into v_previous,v_user_id from public.reviews where id=p_review_id for update; if v_previous is null then raise exception using errcode='22023',message='Review not found.'; end if; v_next:=case p_action when 'publish' then 'published' when 'request_correction' then 'needs_correction' when 'reject' then 'rejected' when 'hide' then 'hidden_under_review' when 'restore' then 'published' else null end; if v_next is null or (p_action='publish' and v_previous not in ('submitted','pending','needs_correction')) or (p_action='request_correction' and v_previous not in ('submitted','pending')) or (p_action='reject' and v_previous not in ('submitted','pending','needs_correction')) or (p_action='hide' and v_previous<>'published') or (p_action='restore' and v_previous<>'hidden_under_review') then raise exception using errcode='22023',message='Invalid review moderation transition.'; end if; update public.reviews set status=v_next,updated_at=current_timestamp,published_at=case when v_next='published' then coalesce(published_at,current_timestamp) else published_at end where id=p_review_id; if v_next='published' and v_user_id is not null then update public.profiles set has_unlocked_tea=true where id=v_user_id; end if; insert into public.moderation_actions(content_type,content_id,action,note,actor_id) values('review',p_review_id,p_action,nullif(btrim(p_note),''),auth.uid()); return jsonb_build_object('review_id',p_review_id,'previous_status',v_previous,'status',v_next); end; $$; revoke all on function public.moderate_inpolor_review(uuid,text,text) from public,anon; grant execute on function public.moderate_inpolor_review(uuid,text,text) to authenticated;
